// Smartsheet on an API access token: every operation of Smartsheet API 2.0 (sheets, rows, cells, columns, reports,
// dashboards, workspaces, folders, sharing, discussions, attachments, proofs, update requests, users, groups, events,
// webhooks). actions.json is generated by `bun scripts/openapi-actions.ts smartsheet` from Smartsheet's own spec; a few
// hand-written ones on top download files and attach links. Changes on a sheet start automations by webhook
// (triggers.ts); new sheets, reports, dashboards, workspaces and admin events are polled (polls/smartsheet.ts).
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { call, type Send, specActions } from "../openapi";
import { api, home } from "./api";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const get = (path: string, query: string[] = []): Send => ({ method: "GET", path, query, headers: [] });
const ME = get("/users/me");
const id = z.union([z.number(), z.string()]);

// a file Smartsheet hands back, read into the chat's computer
async function download(key: string, path: string, accept: string, name: string, query: Record<string, string> = {}) {
  const q = new URLSearchParams(query);
  const res = await fetch(`${api.url!(key, api.base, path)}${q.size ? `?${q}` : ""}`, { headers: { ...api.auth!(key, {}), Accept: accept } });
  if (!res.ok) throw new AppsError(`Smartsheet: couldn't download ${name} (${res.status})`, res.status === 401);
  return new AppFile(name, accept, new Uint8Array(await res.arrayBuffer()));
}
const FORMATS = { csv: "text/csv", xlsx: "application/vnd.ms-excel", pdf: "application/pdf" } as const;

const hand: Record<string, OwnAction> = {
  export_sheet: {
    description: "Download a whole sheet as an Excel file, a PDF or a CSV, into the chat's computer. For reading its data, get_sheet is better.",
    readOnly: true,
    input: z.object({
      sheetId: id.describe("The sheet's id (list_sheets lists them)"),
      format: z.enum(["xlsx", "pdf", "csv"]).describe("xlsx (Excel), pdf or csv"),
      paperSize: z.enum(["LETTER", "LEGAL", "WIDE", "ARCHD", "A4", "A3", "A2", "A1", "A0"]).optional().describe("PDF only: the page size (LETTER if left out)"),
    }),
    run: (i: { sheetId: string | number; format: keyof typeof FORMATS; paperSize?: string }, key: string) =>
      download(key, `/sheets/${encodeURIComponent(String(i.sheetId))}`, FORMATS[i.format], `sheet-${i.sheetId}.${i.format}`, i.paperSize ? { paperSize: i.paperSize } : {}),
  },
  export_report: {
    description: "Download a report as an Excel file or a CSV, into the chat's computer. For reading its data, get_report is better.",
    readOnly: true,
    input: z.object({ reportId: id.describe("The report's id (list_reports lists them)"), format: z.enum(["xlsx", "csv"]).describe("xlsx (Excel) or csv") }),
    run: (i: { reportId: string | number; format: "xlsx" | "csv" }, key: string) =>
      download(key, `/reports/${encodeURIComponent(String(i.reportId))}`, FORMATS[i.format], `report-${i.reportId}.${i.format}`),
  },
  download_attachment: {
    description: "Download a file attached to a sheet, row or comment, into the chat's computer. Links (Google Drive, Dropbox, a web page) come back as their address instead.",
    readOnly: true,
    input: z.object({ sheetId: id.describe("The sheet's id"), attachmentId: id.describe("The attachment's id (list_sheet_attachments or list_row_attachments lists them)") }),
    async run(i: { sheetId: string | number; attachmentId: string | number }, key: string) {
      const a = (await call(api, key, get("/sheets/{sheetId}/attachments/{attachmentId}"), i)) as { name: string; url?: string; mimeType?: string; attachmentType?: string };
      if (a.attachmentType !== "FILE" || !a.url) return { name: a.name, type: a.attachmentType, url: a.url };
      // a short-lived link to the file itself, which takes no token
      const res = await fetch(a.url);
      if (!res.ok) throw new AppsError(`Smartsheet: couldn't download ${a.name} (${res.status})`);
      return new AppFile(a.name, a.mimeType || res.headers.get("content-type")?.split(";")[0] || "application/octet-stream", new Uint8Array(await res.arrayBuffer()));
    },
  },
  attach_link: {
    description: "Attach a link (a web page, a Google Drive, Dropbox, OneDrive, Box or Evernote file) to a sheet, a row or a comment. To attach a file from the computer, use attach_to_sheet, attach_to_row or attach_to_comment.",
    input: z.object({
      sheetId: id.describe("The sheet's id"),
      rowId: id.optional().describe("Attach it to this row (its id) instead of the whole sheet"),
      commentId: id.optional().describe("Attach it to this comment (its id) instead of the whole sheet"),
      url: z.string().describe("The link"),
      name: z.string().optional().describe("What to call it (the link itself if left out)"),
      description: z.string().optional().describe("A note about it"),
      attachmentType: z.enum(["LINK", "GOOGLE_DRIVE", "DROPBOX", "ONEDRIVE", "BOX_COM", "EVERNOTE", "EGNYTE"]).default("LINK").describe("What kind of link: LINK for a web page, or the service the file is in"),
    }),
    run(i: { sheetId: string | number; rowId?: string | number; commentId?: string | number; url: string; name?: string; description?: string; attachmentType: string }, key: string) {
      const on = i.rowId ? "/rows/{rowId}" : i.commentId ? "/comments/{commentId}" : "";
      const send: Send = { method: "POST", path: `/sheets/{sheetId}${on}/attachments`, query: [], headers: [], body: { kind: "fields", fields: ["url", "name", "description", "attachmentType"].map((f): [string, string] => [f, f]) } };
      return call(api, key, send, { ...i, name: i.name ?? i.url });
    },
  },
};

// every call first finds the token's region
const actions: Record<string, OwnAction> = { ...(await specActions(new URL("./actions.json", import.meta.url), api)), ...hand };
for (const a of Object.values(actions)) {
  const run = a.run;
  a.run = async (input, key, connection) => (await home(key), run(input, key, connection));
}

export const smartsheet: OwnApp = {
  app: "smartsheet",
  name: "Smartsheet",
  logo: "/logos/smartsheet.svg",
  keyField: {
    label: "API access token",
    help: "In Smartsheet, click your picture (bottom left) → Personal Settings → API Access → Generate new access token, name it Emplio and copy it (it's shown only once). Emplio can then see and change whatever your Smartsheet account can. Accounts in the EU, Australia and Smartsheet Gov work too. On some company plans an admin has to allow API access first.",
    placeholder: "aBcD1234eFgH5678iJkL...",
  },
  async check(key) {
    await home(key);
    const me = (await call(api, key, ME, {})) as { email?: string; firstName?: string; lastName?: string; account?: { name?: string } };
    const who = [me.firstName, me.lastName].filter(Boolean).join(" ") || me.email || "Smartsheet";
    return me.account?.name && me.account.name !== who ? `${who} (${me.account.name})` : who;
  },
  push: {
    events,
    triggers,
    start: async (key, connection, event, config) => (await home(key), watch(key, connection, event, config)),
    stop: async (key, id) => (await home(key), unwatch(key, id)),
    receive: async (delivery, key) => receive(delivery, key),
    wanted,
  },
  actions,
};
